<template>
  <section class="page-stack wide-workspace"><header class="page-heading"><span class="kicker">Controlled Governance</span><h1>受控操作治理</h1><p>治理状态只决定工程评估路径，不会赋予新的运行时权限。</p></header><div class="warning-banner info"><strong>治理边界</strong><p>“可进入简化评估”不代表自动执行；当前仍需治疗师审批和显式 Apply。</p></div><p v-if="error" class="inline-notice danger" role="alert">{{ error }}</p><p v-if="notice" class="inline-notice" role="status">{{ notice }}</p>
    <div class="panel-grid two"><form class="form-panel compact-form" @submit.prevent="create"><h2>创建治理数据集</h2><label>名称<input v-model="name" required /></label><label>版本<input v-model="version" required /></label><button class="primary-button">创建</button></form><form class="form-panel compact-form" @submit.prevent="add"><h2>添加受控提案</h2><label>Dataset ID<input v-model="datasetId" required /></label><label>Proposal ID<input v-model="proposalId" required /></label><button class="secondary-button">添加</button></form></div>
    <section class="workspace-panel"><h2>冻结与评估</h2><div class="inline-form"><label>Dataset ID<input v-model="datasetId"/></label><label>动作类型<select v-model="actionType"><option value="">全部支持类型</option><option value="training_focus_override">training_focus_override</option><option value="difficulty_step_adjustment">difficulty_step_adjustment</option></select></label><button class="secondary-button danger" :disabled="!datasetId" @click="confirmFreeze=true">冻结</button><button class="primary-button" :disabled="!datasetId" @click="run">运行治理评估</button></div><div v-if="runs.length" class="panel-grid two"><article v-for="r in runs" :key="r.id" class="surface-card"><StatusBadge :status="r.status"/><JsonDetails :value="r.report"/><div class="reason-list"><span v-for="code in r.reason_codes" :key="code"><strong>{{ explainReasonCode(code) }}</strong><code>{{ code }}</code></span></div></article></div></section>
    <section class="workspace-panel"><div class="section-heading"><div><h2>Governance registry</h2><p>按 action type 独立治理。</p></div><button class="secondary-button" @click="loadRegistry">刷新</button></div><AsyncState :loading="loading" :error="registryError" :empty="registry.length===0" @retry="loadRegistry"><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Policy / Rules</th><th>Action type</th><th>治理状态</th><th>解释</th></tr></thead><tbody><tr v-for="row in registry" :key="`${row.policy_version}-${row.rules_version}-${row.action_type}`"><td>{{ row.policy_version }}<small>{{ row.rules_version }}</small></td><td>{{ row.action_type }}</td><td><StatusBadge :status="row.governance_status"/></td><td>{{ statusDescription(row.governance_status) }}</td></tr></tbody></table></div></AsyncState></section>
    <ConfirmDialog :open="confirmFreeze" title="冻结治理数据集？" message="冻结后数据集条目不可再编辑，之后才能运行治理评估。" confirm-label="确认冻结" danger @cancel="confirmFreeze=false" @confirm="freeze" />
  </section>
</template>
<script setup lang="ts">
import { onMounted,ref } from 'vue'; import { governanceApi } from '@/api/governance'; import AsyncState from '@/components/common/AsyncState.vue'; import ConfirmDialog from '@/components/common/ConfirmDialog.vue'; import JsonDetails from '@/components/common/JsonDetails.vue'; import StatusBadge from '@/components/common/StatusBadge.vue'; import { explainReasonCode } from '@/utils/reasonCodes'; import { presentStatus } from '@/utils/status'; import type { GovernanceRun,RegistryEntry } from '@/types/professional'
const name=ref(''),version=ref('governance-v1'),datasetId=ref(''),proposalId=ref(''),actionType=ref(''),registry=ref<RegistryEntry[]>([]),runs=ref<GovernanceRun[]>([]),loading=ref(true),registryError=ref(''),error=ref(''),notice=ref(''),confirmFreeze=ref(false); const msg=(e:unknown)=>e instanceof Error?e.message:'操作失败'; const statusDescription=(s?:string)=>presentStatus(s).description
async function create(){try{const r=await governanceApi.createDataset(name.value,version.value);datasetId.value=r.id;notice.value='治理数据集已创建。'}catch(e){error.value=msg(e)}} async function add(){try{await governanceApi.addItem(datasetId.value,proposalId.value);notice.value='提案已加入治理数据集。'}catch(e){error.value=msg(e)}} async function freeze(){try{await governanceApi.freeze(datasetId.value);confirmFreeze.value=false;notice.value='治理数据集已冻结。'}catch(e){error.value=msg(e)}} async function run(){try{runs.value=await governanceApi.run(datasetId.value,actionType.value||undefined);notice.value='治理评估完成。';await loadRegistry()}catch(e){error.value=msg(e)}} async function loadRegistry(){loading.value=true;registryError.value='';try{registry.value=await governanceApi.registry()}catch(e){registryError.value=msg(e)}finally{loading.value=false}} onMounted(loadRegistry)
</script>
